sys.setrecursionlimit(2000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        p = int(next(iterator))

        A = []
        for _ in range(N):
            row = []
            for _ in range(N):
                row.append(int(next(iterator)))
            A.append(row)
    except StopIteration:
        return

    # Handle p=2 specially
    # When p=2, p-1=1. The condition for a path to have non-zero contribution 
    # (that for every zero-position edge used, the count is divisible by p-1)
    # becomes vacuous (always true).
    # Also, the sum over variable choices for a zero-position edge with count m is
    # sum_{x=1}^{1} x^m = 1^m = 1.
    # Thus, for every path, the contribution is simply the product of A entries for 
    # non-zero edges, and 1 for zero edges.
    # This is equivalent to constructing a matrix A_mod where 0s are replaced by 1s,
    # and computing (A_mod)^p mod 2.
    if p == 2:
        A_mod = [[1 if x == 0 else x for x in row] for row in A]

        def mat_mul_mod2(X, Y, n):
            Z = [[0] * n for _ in range(n)]
            for i in range(n):
                for k in range(n):
                    if X[i][k]:
                        for j in range(n):
                            Z[i][j] ^= (X[i][k] & Y[k][j])
            return Z

        def mat_pow_mod2(X, power, n):
            res = [[0] * n for _ in range(n)]
            for i in range(n): res[i][i] = 1
            base = X
            while power > 0:
                if power % 2 == 1:
                    res = mat_mul_mod2(res, base, n)
                base = mat_mul_mod2(base, base, n)
                power //= 2
            return res

        final_res = mat_pow_mod2(A_mod, p, N)
        for row in final_res:
            print(*(row))
        return

    # General case p > 2
    # Count zeros K
    K = 0
    zeros = []
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                K += 1
                zeros.append((i, j))

    # Matrix Multiplication
    def mat_mul(X, Y, mod, n):
        Z = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if X[i][k] != 0:
                    r_val = X[i][k]
                    for j in range(n):
                        if Y[k][j] != 0:
                            Z[i][j] = (Z[i][j] + r_val * Y[k][j]) % mod
        return Z

    # Matrix Power
    def mat_pow(X, power, mod, n):
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            res[i][i] = 1
        base = [row[:] for row in X]
        while power > 0:
            if power % 2 == 1:
                res = mat_mul(res, base, mod, n)
            base = mat_mul(base, base, mod, n)
            power //= 2
        return res

    # A_res: A with 0s at original 0s. Since A contains 0s, A itself works.
    # We use A directly as A_res.
    # M1 = A_res^p (treating zeros as zeros) corresponds to paths with NO zero edges used.
    M1 = mat_pow(A, p, p, N)

    # Prepare add matrix for contributions from paths with exactly one zero edge used (count p-1)
    add = [[0] * N for _ in range(N)]

    # Iterate over zeros
    for (u, v) in zeros:
        if u == v:
            # Self loop zero at (u, u)
            # For each non-zero edge connected to u, we add its value to add matrix.
            # Specifically, if edge f=(u, k) is non-zero, it adds A[u][k] to S_{u,k}.
            # If edge f=(k, u) is non-zero, it adds A[k][u] to S_{k,u}.
            for k in range(N):
                val_out = A[u][k]
                if val_out != 0:
                    add[u][k] = (add[u][k] + val_out) % p

                val_in = A[k][u]
                if val_in != 0:
                    add[k][u] = (add[k][u] + val_in) % p
        else:
            # Not self loop
            # For p > 3, no such paths exist.
            # For p == 3, a path exists if there is a non-zero edge f=(v, u).
            # Such a path contributes to S_{u,v}.
            if p == 3:
                val = A[v][u]
                if val != 0:
                    add[u][v] = (add[u][v] + val) % p

    # Combine M1 and add with sign
    # Global factor (-1)^K comes from summing over unused zero variables and the used zero variable.
    sign = 1
    if K % 2 == 1:
        sign = (p - 1) % p 

    # Final answer = sign * (M1 + add)
    for i in range(N):
        line = []
        for j in range(N):
            val = (M1[i][j] + add[i][j]) % p
            val = (val * sign) % p
            line.append(str(val))
        print(" ".join(line))

if __name__ == '__main__':
    solve()
